// Fonts EMBEDDED into every server-rendered PDF, as base64 woff2.
//
// WHY THIS FILE EXISTS. The PDF templates all declared
//
//     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif
//
// which is the app's own stack, and which resolves beautifully IN A BROWSER — the LP
// report cards are printed client-side (window.print()), so they picked up the reader's
// real system font. But the PDFs generated on the server go through headless Chromium
// (@sparticuz/chromium on Vercel), a container with essentially no fonts installed: no
// -apple-system, no Segoe UI, no Roboto, no Helvetica. Every one of those fell through to
// the container's default sans — a Calibri-metric face — so the LP capital statement and
// the portal's snapshot PDFs came out in Calibri while the GP's browser-printed report
// card came out in San Francisco. Same CSS, different renderer, two different documents.
//
// Shipping the actual system font is not an option (San Francisco is Apple-licensed), so
// the fix is to stop depending on the host having fonts at all: embed one. Inter is the
// standard stand-in for the system UI stack — it is metrically and visually close to San
// Francisco and Segoe UI, which is why it reads as "the app's font" rather than as a
// third typeface. Roboto Mono replaces the bare `monospace` the figures used, for the
// same reason: `monospace` in that container is whatever it happens to be.
//
// Embedded rather than fetched: a PDF render must not depend on the network, and a font
// that fails to download silently produces a Calibri document — the exact bug this fixes.
//
// Regenerate: fetch the woff2 from fontsource and base64 it. Latin subsets only, ~85KB
// for the Inter + Roboto Mono set, which is cheap next to a Chromium cold start.
//
// The DISPLAY faces (Newsreader / Source Serif 4 / Libre Caslon Display) are the
// per-fund report font, FundTheme.displayFont. Only the one a fund selected is
// embedded per render — see pdfFontCss below — because emitting all three would add
// ~76KB of base64 to every document for two faces it will never reference.

const INTER_400 = ''

const INTER_600 = ''

const INTER_700 = ''

const MONO_400 = ''


const NEWSREADER_400 = ''

const SOURCESERIF_400 = ''

const CASLON_400 = ''

/**
 * Font families and the @font-face block for server-rendered PDFs.
 *
 * Every server-rendered PDF template must include `pdfFontCss(...)` in its <style>
 * AND use `font-family: ${PDF_SANS}` / `${PDF_DISPLAY}` — declaring the faces
 * without referencing them does nothing, which is an easy and silent mistake.
 */
export const PDF_SANS = `'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif`
export const PDF_MONO = `'Roboto Mono', ui-monospace, SFMono-Regular, Menlo, monospace`
// 'Inter' sits second on purpose. On the default theme no PDFDisplay face is
// emitted at all, so this stack falls through to the Inter already embedded as
// the body face — the default display font costs zero extra bytes per render.
export const PDF_DISPLAY = `'PDFDisplay', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif`

/** SERIF display faces a fund may pick, keyed by DISPLAY_FONT_OPTIONS in
 *  lib/theme.ts. The default ('inter') is deliberately absent — see PDF_DISPLAY. */
const DISPLAY_FACES: Record<string, string> = {
  'newsreader': NEWSREADER_400,
  'source-serif': SOURCESERIF_400,
  'libre-caslon': CASLON_400,
}

/**
 * @font-face block to inline into a PDF template's <style>.
 *
 * Only the ONE display face the fund selected is embedded — all three would add
 * ~76KB of base64 to every render for two faces that document will never use.
 * The chosen face is always emitted under the same family name ('PDFDisplay') so
 * templates can reference ${PDF_DISPLAY} without knowing which font it resolved to.
 *
 * Unknown or absent keys, and the 'inter' default, emit NO display face: the
 * PDF_DISPLAY stack then falls through to the Inter already embedded below, so
 * the default costs nothing rather than carrying a second copy of Inter.
 */
export function pdfFontCss(displayFont?: string | null): string {
  const display = DISPLAY_FACES[displayFont ?? '']
  return `
  @font-face { font-family:'Inter'; font-style:normal; font-weight:400; font-display:block; src:url(data:font/woff2;base64,${INTER_400}) format('woff2'); }
  @font-face { font-family:'Inter'; font-style:normal; font-weight:600; font-display:block; src:url(data:font/woff2;base64,${INTER_600}) format('woff2'); }
  @font-face { font-family:'Inter'; font-style:normal; font-weight:700; font-display:block; src:url(data:font/woff2;base64,${INTER_700}) format('woff2'); }
  @font-face { font-family:'Roboto Mono'; font-style:normal; font-weight:400; font-display:block; src:url(data:font/woff2;base64,${MONO_400}) format('woff2'); }
${display ? `  @font-face { font-family:'PDFDisplay'; font-style:normal; font-weight:400; font-display:block; src:url(data:font/woff2;base64,${display}) format('woff2'); }` : ''}
`
}

/** Back-compat: the default (Inter) font block — no PDFDisplay face. */
export const PDF_FONT_CSS = pdfFontCss()
